import * as THREE from 'three';
import {random} from './track.js';
export class Particles{
 constructor(scene){this.rng=random(3401);this.items=Array.from({length:180},()=>({life:0,p:new THREE.Vector3(),v:new THREE.Vector3()}));this.positions=new Float32Array(540);this.colors=new Float32Array(540);this.geometry=new THREE.BufferGeometry();this.geometry.setAttribute('position',new THREE.BufferAttribute(this.positions,3));this.geometry.setAttribute('color',new THREE.BufferAttribute(this.colors,3));const c=document.createElement('canvas');c.width=c.height=1024;const ctx=c.getContext('2d'),g=ctx.createRadialGradient(512,512,0,512,512,512);g.addColorStop(0,'#ffffff70');g.addColorStop(.4,'#ffffff35');g.addColorStop(1,'#ffffff00');ctx.fillStyle=g;ctx.fillRect(0,0,1024,1024);this.mesh=new THREE.Points(this.geometry,new THREE.PointsMaterial({size:.7,map:new THREE.CanvasTexture(c),vertexColors:true,transparent:true,depthWrite:false,opacity:.6}));this.mesh.frustumCulled=false;this.mesh.userData.exempt='particles';scene.add(this.mesh);this.cursor=0;}
 update(dt,vehicles,active){if(active)for(const v of vehicles)if(v.speed>8&&(v.slip>.18||v.offroad)&&this.rng()<dt*35){const p=this.items[this.cursor++%this.items.length],side=this.rng()>.5?1:-1;p.p.copy(v.position);p.p.x-=Math.sin(v.yaw)*1.4+Math.cos(v.yaw)*side*.85;p.p.z-=Math.cos(v.yaw)*1.4-Math.sin(v.yaw)*side*.85;p.p.y+=.16;p.v.set((this.rng()-.5)*1.2,.35+this.rng()*.3,(this.rng()-.5)*1.2);p.life=1.25;p.dust=v.offroad;}
  this.items.forEach((p,i)=>{p.life-=dt;p.p.addScaledVector(p.v,dt);this.positions.set(p.life>0?p.p.toArray():[0,-1000,0],i*3);const alpha=Math.max(0,p.life/1.25);this.colors.set(p.dust?[.8*alpha,.68*alpha,.44*alpha]:[.65*alpha,.7*alpha,.73*alpha],i*3);});this.geometry.attributes.position.needsUpdate=true;this.geometry.attributes.color.needsUpdate=true;}
}

